test.beforeAll(async () => mkdir(output, { recursive: true }));

test("Jobs to Job Detail to Analysis preserves deterministic workflow", async ({
  page,
}) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await disableDevelopmentToolbar(page);
  await seed(page);
  await page.goto("/dashboard/jobs");
  await assertVisualContract(page);
  await page.screenshot({
    path: `${output}/jobs-empty-1440x900.png`,
    fullPage: false,
  });

  await page.getByRole("button", { name: "Add a job" }).first().click();
  await page.getByLabel("Job description").fill(vacancy);
  await page.getByRole("button", { name: "Save job" }).click();
  await expect(
    page.getByRole("heading", { name: "Senior Product Analyst" }),
  ).toBeVisible();
  await assertVisualContract(page);
  await page.screenshot({
    path: `${output}/jobs-populated-1440x900.png`,
    fullPage: false,
  });

  await page.getByRole("button", { name: "Review and analyse" }).click();
  await expect(
    page.getByRole("tablist", { name: "Job sections" }),
  ).toBeVisible();
  const overviewTab = page.getByRole("tab", { name: "Overview" });
  const analysisTab = page.getByRole("tab", { name: "Analysis" });
  await expect(overviewTab).toHaveAttribute("aria-selected", "true");
  await expect(overviewTab).toHaveCSS("box-shadow", "none");
  await expect(analysisTab).toHaveCSS("background-color", "rgba(0, 0, 0, 0)");
  await expect(page.getByLabel("Extracted job facts")).toBeVisible();
  await assertVisualContract(page);
  await page.screenshot({
    path: `${output}/job-detail-1440x900.png`,
    fullPage: false,
  });

  await page.getByRole("button", { name: "Analyse job" }).click();
  await expect(analysisTab).toHaveAttribute("aria-selected", "true");
  await expect(analysisTab).toHaveCSS("background-color", "rgba(0, 0, 0, 0)");
  await expect(page.getByText("Consider", { exact: true })).toBeVisible();
  await expect(
    page.getByRole("heading", { name: "Resolve the unknowns" }),
  ).toBeVisible();
  await expect(
    page.getByText("Vacancy-specific sponsorship wording", { exact: true }),
  ).toBeVisible();
  await expect(
    page.locator(".phase-two-decision-copy").getByText(/analysis version 1/i),
  ).toBeVisible();
  await expect(page.locator(".phase-two-decision-score")).toHaveAccessibleName(
    "2 of 2 requirements have supporting evidence",
  );
  await assertVisualContract(page);
  await page.screenshot({
    path: `${output}/analysis-consider-1440x900.png`,
    fullPage: false,
  });
  const stored = await page.evaluate(
    ({ userId }) =>
      JSON.parse(
        localStorage.getItem(`autotime-phase-3b-workflow-v1:${userId}`) ||
          "null",
      ),
    { userId },
  );
  expect(stored.jobs[0].analysisHistory).toHaveLength(1);
  expect(stored.jobs[0].analysisHistory[0].decision).toBe("Consider");
  expect(stored.jobs[0].analysisHistory[0].coverage).toBe(100);
});

test("Phase 2 remains readable and operable on mobile", async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await disableDevelopmentToolbar(page);
  await seed(page);
  await page.goto("/dashboard/jobs");
  await page.getByRole("button", { name: "Add a job" }).first().click();
  await page.getByLabel("Job description").fill(vacancy);
  await page.getByRole("button", { name: "Save job" }).click();
  await page.getByRole("button", { name: "Review and analyse" }).click();
  const analysisTab = page.getByRole("tab", { name: "Analysis" });
  await page.getByRole("button", { name: "Analyse job" }).click();
  await expect(analysisTab).toHaveAttribute("aria-selected", "true");
  await expect(analysisTab).toHaveCSS("background-color", "rgba(0, 0, 0, 0)");
  await assertVisualContract(page);
  const overviewTab = page.getByRole("tab", { name: "Overview" });
  for (let index = 0; index < 20; index += 1) {
    await page.keyboard.press("Tab");
    if (
      await overviewTab.evaluate(
        (element) => element === document.activeElement,
      )
    )
      break;
  }
  await expect(overviewTab).toBeFocused();
  await expect(overviewTab).toHaveCSS("outline-style", "none");
  await expect(overviewTab).toHaveCSS("text-decoration-line", "none");
  await expect
    .poll(() =>
      overviewTab.evaluate(
        (element) => getComputedStyle(element, "::before").backgroundColor,
      ),
    )
    .toBe("rgb(81, 69, 205)");
  await expect(page.locator(":focus")).toBeVisible();
  const targets = await page
    .locator(
      "main.phase-two-jobs button:visible, main.phase-two-jobs a:visible",
    )
    .evaluateAll((elements) =>
      elements.map((element) => {
        const box = element.getBoundingClientRect();
        return { width: box.width, height: box.height };
      }),
    );
  expect(
    targets.every(({ width, height }) => width >= 44 || height >= 44),
  ).toBe(true);
  await page.evaluate(() => {
    if (document.activeElement instanceof HTMLElement)
      document.activeElement.blur();
  });
  await page.screenshot({
    path: `${output}/analysis-consider-390x844.png`,
    fullPage: false,
  });
});
